{"implementation":"from fractions import Fraction
import heapq


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    if "segments" not in case or "budget" not in case:
        raise ValueError("missing required fields")

    segments = case["segments"]
    budget = case["budget"]
    if not isinstance(segments, list):
        raise ValueError("segments must be a list")
    if type(budget) is not int:
        raise ValueError("budget must be an integer")

    names = []
    importances = []
    minimums = []
    capacities = []
    seen_names = set()

    for segment in segments:
        if not isinstance(segment, dict):
            raise ValueError("each segment must be a dict")
        for key in ("name", "importance", "minimum", "capacity"):
            if key not in segment:
                raise ValueError(f"missing required segment field: {key}")
        name = segment["name"]
        importance = segment["importance"]
        minimum = segment["minimum"]
        capacity = segment["capacity"]
        if type(name) is not str:
            raise ValueError("segment name must be a string")
        if type(importance) is not int or type(minimum) is not int or type(capacity) is not int:
            raise ValueError("segment weights and quotas must be integers")
        if importance < 0 or minimum < 0 or capacity < 0:
            raise ValueError("segment values must be non-negative")
        if minimum > capacity:
            raise ValueError("minimum cannot exceed capacity")
        if name in seen_names:
            raise ValueError("segment names must be unique")
        seen_names.add(name)
        names.append(name)
        importances.append(importance)
        minimums.append(minimum)
        capacities.append(capacity)

    min_total = sum(minimums)
    cap_total = sum(capacities)
    if budget < min_total:
        raise ValueError("budget below minimum quota sum")
    if budget > cap_total:
        raise ValueError("budget above total capacity")

    allocations = minimums[:]
    remaining = budget - min_total
    heap = []

    for idx, importance in enumerate(importances):
        if allocations[idx] < capacities[idx]:
            priority = Fraction(importance, allocations[idx] + 1)
            heapq.heappush(heap, (-priority, idx))

    while remaining > 0:
        if not heap:
            raise ValueError("insufficient capacity for remaining budget")
        _, idx = heapq.heappop(heap)
        allocations[idx] += 1
        remaining -= 1
        if allocations[idx] < capacities[idx]:
            priority = Fraction(importances[idx], allocations[idx] + 1)
            heapq.heappush(heap, (-priority, idx))

    by_name = {names[i]: allocations[i] for i in range(len(names))}
    return {"allocations": allocations, "by_name": by_name, "total": sum(allocations)}"}
